UPDATE projects
SET title = #{title},
    description = #{description},
    status = #{status}
WHERE id = #{id}

UPDATE project_members
SET is_approved = 1
WHERE project_id = #{projectId} AND user_id = #{userId}

UPDATE project_members
SET role = #{newRole}
WHERE project_id = #{projectId} AND user_id = #{userId}

UPDATE project_tasks
SET title = #{title}, description = #{description}, start_date = #{startDate}, due_date = #{dueDate}, assigned_to = #{assignedTo}, status = #{status}, priority = #{priority}, color = #{color}
WHERE id = #{id}

